88	  /**
89	   * Currently, used by Client and AM only
90	   * Create a proxy for the specified protocol. For non-HA,
91	   * this is a direct connection to the ResourceManager address. When HA is
92	   * enabled, the proxy handles the failover between the ResourceManagers as
93	   * well.
94	   */
95	  @Private
96	  protected static <T> T createRMProxy(final Configuration configuration,
97	      final Class<T> protocol, RMProxy<T> instance) throws IOException {
98	    YarnConfiguration conf = (configuration instanceof YarnConfiguration)
99	        ? (YarnConfiguration) configuration
100	        : new YarnConfiguration(configuration);
101	    RetryPolicy retryPolicy = createRetryPolicy(conf,
102	        (HAUtil.isHAEnabled(conf) || HAUtil.isFederationFailoverEnabled(conf)));
103	    return newProxyInstance(conf, protocol, instance, retryPolicy);
104	  }
