106	  /**
107	   * Currently, used by NodeManagers only.
108	   * Create a proxy for the specified protocol. For non-HA,
109	   * this is a direct connection to the ResourceManager address. When HA is
110	   * enabled, the proxy handles the failover between the ResourceManagers as
111	   * well.
112	   */
113	  @Private
114	  protected static <T> T createRMProxy(final Configuration configuration,
115	      final Class<T> protocol, RMProxy<T> instance, final long retryTime,
116	      final long retryInterval) throws IOException {
117	    YarnConfiguration conf = (configuration instanceof YarnConfiguration)
118	        ? (YarnConfiguration) configuration
119	        : new YarnConfiguration(configuration);
120	    RetryPolicy retryPolicy = createRetryPolicy(conf, retryTime, retryInterval,
121	        HAUtil.isHAEnabled(conf));
122	    return newProxyInstance(conf, protocol, instance, retryPolicy);
123	  }
124	
125	  private static <T> T newProxyInstance(final YarnConfiguration conf,
126	      final Class<T> protocol, RMProxy<T> instance, RetryPolicy retryPolicy)
127	          throws IOException{
128	    RMFailoverProxyProvider<T> provider;
129	    if (HAUtil.isHAEnabled(conf) || HAUtil.isFederationEnabled(conf)) {
130	      provider = instance.createRMFailoverProxyProvider(conf, protocol);
131	    } else {
132	      provider = instance.createNonHaRMFailoverProxyProvider(conf, protocol);
133	    }
134	    return (T) RetryProxy.create(protocol, provider, retryPolicy);
135	  }
