143	      final Class<T> protocol, final InetSocketAddress rmAddress)
144	      throws IOException {
145	    return user.doAs(
146	      new PrivilegedAction<T>() {
147	        @Override
148	        public T run() {
149	          return (T) YarnRPC.create(conf).getProxy(protocol, rmAddress, conf);
150	        }
151	      });
152	  }
