157	  private <T> RMFailoverProxyProvider<T> createNonHaRMFailoverProxyProvider(
158	      Configuration conf, Class<T> protocol) {
159	    Class<? extends RMFailoverProxyProvider<T>> defaultProviderClass;
160	    try {
161	      defaultProviderClass = (Class<? extends RMFailoverProxyProvider<T>>)
162	          Class.forName(
163	              YarnConfiguration.DEFAULT_CLIENT_FAILOVER_NO_HA_PROXY_PROVIDER);
164	    } catch (Exception e) {
165	      throw new YarnRuntimeException("Invalid default failover provider class" +
166	          YarnConfiguration.DEFAULT_CLIENT_FAILOVER_NO_HA_PROXY_PROVIDER, e);
167	    }
168	
169	    RMFailoverProxyProvider<T> provider = ReflectionUtils.newInstance(
170	        conf.getClass(YarnConfiguration.CLIENT_FAILOVER_NO_HA_PROXY_PROVIDER,
171	            defaultProviderClass, RMFailoverProxyProvider.class), conf);
172	    provider.init(conf, (RMProxy<T>) this, protocol);
173	    return provider;
174	  }
