198	  /**
199	   * Fetch retry policy from Configuration
200	   */
201	  @Private
202	  @VisibleForTesting
203	  public static RetryPolicy createRetryPolicy(Configuration conf,
204	      boolean isHAEnabled) {
205	    long rmConnectWaitMS =
206	        conf.getLong(
207	            YarnConfiguration.RESOURCEMANAGER_CONNECT_MAX_WAIT_MS,
208	            YarnConfiguration.DEFAULT_RESOURCEMANAGER_CONNECT_MAX_WAIT_MS);
209	    long rmConnectionRetryIntervalMS =
210	        conf.getLong(
211	            YarnConfiguration.RESOURCEMANAGER_CONNECT_RETRY_INTERVAL_MS,
212	            YarnConfiguration
213	                .DEFAULT_RESOURCEMANAGER_CONNECT_RETRY_INTERVAL_MS);
214	
215	    return createRetryPolicy(conf, rmConnectWaitMS, rmConnectionRetryIntervalMS,
216	        isHAEnabled);
217	  }
218	
219	  /**
220	   * Fetch retry policy from Configuration and create the
221	   * retry policy with specified retryTime and retry interval.
222	   */
223	  protected static RetryPolicy createRetryPolicy(Configuration conf,
224	      long retryTime, long retryInterval, boolean isHAEnabled) {
225	    long rmConnectWaitMS = retryTime;
226	    long rmConnectionRetryIntervalMS = retryInterval;
227	
228	    boolean waitForEver = (rmConnectWaitMS == -1);
229	    if (!waitForEver) {
230	      if (rmConnectWaitMS < 0) {
231	        throw new YarnRuntimeException("Invalid Configuration. "
232	            + YarnConfiguration.RESOURCEMANAGER_CONNECT_MAX_WAIT_MS
233	            + " can be -1, but can not be other negative numbers");
234	      }
235	
236	      // try connect once
237	      if (rmConnectWaitMS < rmConnectionRetryIntervalMS) {
238	        LOG.warn(YarnConfiguration.RESOURCEMANAGER_CONNECT_MAX_WAIT_MS
239	            + " is smaller than "
240	            + YarnConfiguration.RESOURCEMANAGER_CONNECT_RETRY_INTERVAL_MS
241	            + ". Only try connect once.");
242	        rmConnectWaitMS = 0;
243	      }
244	    }
245	
246	    // Handle HA case first
247	    if (isHAEnabled) {
248	      final long failoverSleepBaseMs = conf.getLong(
249	          YarnConfiguration.CLIENT_FAILOVER_SLEEPTIME_BASE_MS,
250	          rmConnectionRetryIntervalMS);
251	
252	      final long failoverSleepMaxMs = conf.getLong(
253	          YarnConfiguration.CLIENT_FAILOVER_SLEEPTIME_MAX_MS,
254	          rmConnectionRetryIntervalMS);
255	
256	      int maxFailoverAttempts = conf.getInt(
257	          YarnConfiguration.CLIENT_FAILOVER_MAX_ATTEMPTS, -1);
258	
259	      if (maxFailoverAttempts == -1) {
260	        if (waitForEver) {
261	          maxFailoverAttempts = Integer.MAX_VALUE;
262	        } else {
263	          maxFailoverAttempts = (int) (rmConnectWaitMS / failoverSleepBaseMs);
264	        }
265	      }
266	
267	      return RetryPolicies.failoverOnNetworkException(
268	          RetryPolicies.TRY_ONCE_THEN_FAIL, maxFailoverAttempts,
269	          failoverSleepBaseMs, failoverSleepMaxMs);
270	    }
271	
272	    if (rmConnectionRetryIntervalMS < 0) {
273	      throw new YarnRuntimeException("Invalid Configuration. " +
274	          YarnConfiguration.RESOURCEMANAGER_CONNECT_RETRY_INTERVAL_MS +
275	          " should not be negative.");
276	    }
277	
278	    RetryPolicy retryPolicy = null;
279	    if (waitForEver) {
280	      retryPolicy = RetryPolicies.retryForeverWithFixedSleep(
281	          rmConnectionRetryIntervalMS, TimeUnit.MILLISECONDS);
282	    } else {
283	      retryPolicy =
284	          RetryPolicies.retryUpToMaximumTimeWithFixedSleep(rmConnectWaitMS,
285	              rmConnectionRetryIntervalMS, TimeUnit.MILLISECONDS);
286	    }
287	
288	    Map<Class<? extends Exception>, RetryPolicy> exceptionToPolicyMap =
289	        new HashMap<Class<? extends Exception>, RetryPolicy>();
290	
291	    exceptionToPolicyMap.put(EOFException.class, retryPolicy);
292	    exceptionToPolicyMap.put(ConnectException.class, retryPolicy);
293	    exceptionToPolicyMap.put(NoRouteToHostException.class, retryPolicy);
294	    exceptionToPolicyMap.put(UnknownHostException.class, retryPolicy);
295	    exceptionToPolicyMap.put(ConnectTimeoutException.class, retryPolicy);
296	    exceptionToPolicyMap.put(RetriableException.class, retryPolicy);
297	    exceptionToPolicyMap.put(SocketException.class, retryPolicy);
298	    exceptionToPolicyMap.put(SocketTimeoutException.class, retryPolicy);
299	    exceptionToPolicyMap.put(StandbyException.class, retryPolicy);
300	    // YARN-4288: local IOException is also possible.
301	    exceptionToPolicyMap.put(IOException.class, retryPolicy);
302	    // Not retry on remote IO exception.
303	    return RetryPolicies.retryOtherThanRemoteException(
304	        RetryPolicies.TRY_ONCE_THEN_FAIL, exceptionToPolicyMap);
305	  }
306	}
