84	   * @param configuration Configuration to generate {@link ClientRMProxy}
85	   * @param protocol Protocol for the proxy
86	   * @param subClusterId the unique identifier or the sub-cluster
87	   * @param user the user on whose behalf the proxy is being created
88	   * @param token the auth token to use for connection
89	   * @param <T> Type information of the proxy
90	   * @return Proxy to the RM
91	   * @throws IOException on failure
92	   */
93	  @Public
94	  @Unstable
95	  public static <T> T createRMProxy(Configuration configuration,
96	      final Class<T> protocol, SubClusterId subClusterId,
97	      UserGroupInformation user, Token<? extends TokenIdentifier> token)
98	      throws IOException {
99	    final YarnConfiguration config = new YarnConfiguration(configuration);
100	    updateConfForFederation(config, subClusterId.getId());
101	    return AMRMClientUtils.createRMProxy(config, protocol, user, token);
102	  }
103	
104	  /**
105	   * Updating the conf with Federation as long as certain subclusterId.
106	   *
107	   * @param conf configuration
108	   * @param subClusterId subclusterId for the conf
109	   */
110	  public static void updateConfForFederation(Configuration conf,
111	      String subClusterId) {
112	    conf.set(YarnConfiguration.RM_CLUSTER_ID, subClusterId);
113	    /*
114	     * In a Federation setting, we will connect to not just the local cluster RM
115	     * but also multiple external RMs. The membership information of all the RMs
116	     * that are currently participating in Federation is available in the
117	     * central FederationStateStore. So we will: 1. obtain the RM service
118	     * addresses from FederationStateStore using the
119	     * FederationRMFailoverProxyProvider. 2. disable traditional HA as that
120	     * depends on local configuration lookup for RMs using indexes. 3. we will
121	     * enable federation failover IF traditional HA is enabled so that the
122	     * appropriate failover RetryPolicy is initialized.
123	     */
124	    conf.setBoolean(YarnConfiguration.FEDERATION_ENABLED, true);
125	    conf.setClass(YarnConfiguration.CLIENT_FAILOVER_PROXY_PROVIDER,
126	        FederationRMFailoverProxyProvider.class, RMFailoverProxyProvider.class);
127	    if (HAUtil.isHAEnabled(conf)) {
128	      conf.setBoolean(YarnConfiguration.FEDERATION_FAILOVER_ENABLED, true);
129	      conf.setBoolean(YarnConfiguration.RM_HA_ENABLED, false);
130	    }
131	  }
