48	/**
49	 * A FailoverProxyProvider implementation that uses the
50	 * {@code FederationStateStore} to determine the ResourceManager to connect to.
51	 * This supports both HA and regular mode which is controlled by configuration.
52	 */
53	@Private
54	@Unstable
55	public class FederationRMFailoverProxyProvider<T>
56	    implements RMFailoverProxyProvider<T> {
57	  private static final Logger LOG =
58	      LoggerFactory.getLogger(FederationRMFailoverProxyProvider.class);
59	
60	  private RMProxy<T> rmProxy;
61	  private Class<T> protocol;
62	  private T current;
63	  private YarnConfiguration conf;
64	  private FederationStateStoreFacade facade;
65	  private SubClusterId subClusterId;
66	  private UserGroupInformation originalUser;
67	  private boolean federationFailoverEnabled;
68	  private boolean flushFacadeCacheForYarnRMAddr;
69	
70	  @Override
71	  public void init(Configuration configuration, RMProxy<T> proxy,
72	      Class<T> proto) {
73	    this.rmProxy = proxy;
74	    this.protocol = proto;
75	    this.rmProxy.checkAllowedProtocols(this.protocol);
76	    String clusterId = configuration.get(YarnConfiguration.RM_CLUSTER_ID);
77	    Preconditions.checkNotNull(clusterId, "Missing RM ClusterId");
78	    this.subClusterId = SubClusterId.newInstance(clusterId);
79	    this.facade = FederationStateStoreFacade.getInstance();
80	    if (configuration instanceof YarnConfiguration) {
81	      this.conf = (YarnConfiguration) configuration;
82	    }
83	    federationFailoverEnabled =
84	        conf.getBoolean(YarnConfiguration.FEDERATION_FAILOVER_ENABLED,
85	            YarnConfiguration.DEFAULT_FEDERATION_FAILOVER_ENABLED);
86	    flushFacadeCacheForYarnRMAddr =
87	        conf.getBoolean(YarnConfiguration.FEDERATION_FLUSH_CACHE_FOR_RM_ADDR,
88	            YarnConfiguration.DEFAULT_FEDERATION_FLUSH_CACHE_FOR_RM_ADDR);
89	
90	    conf.setInt(
91	        CommonConfigurationKeysPublic.IPC_CLIENT_CONNECT_MAX_RETRIES_KEY,
92	        conf.getInt(YarnConfiguration.CLIENT_FAILOVER_RETRIES,
93	            YarnConfiguration.DEFAULT_CLIENT_FAILOVER_RETRIES));
94	
95	    conf.setInt(
96	        CommonConfigurationKeysPublic.IPC_CLIENT_CONNECT_MAX_RETRIES_ON_SOCKET_TIMEOUTS_KEY,
97	        conf.getInt(
98	            YarnConfiguration.CLIENT_FAILOVER_RETRIES_ON_SOCKET_TIMEOUTS,
99	            YarnConfiguration.DEFAULT_CLIENT_FAILOVER_RETRIES_ON_SOCKET_TIMEOUTS));
100	
101	    try {
102	      this.originalUser = UserGroupInformation.getCurrentUser();
103	      LOG.info("Initialized Federation proxy for user: {}",
104	          this.originalUser.getUserName());
105	    } catch (IOException e) {
106	      LOG.warn("Could not get information of requester, ignoring for now.");
107	      this.originalUser = null;
108	    }
109	
110	  }
111	
112	  @VisibleForTesting
113	  protected T createRMProxy(InetSocketAddress rmAddress) throws IOException {
114	    return rmProxy.getProxy(conf, protocol, rmAddress);
115	  }
116	
117	  private T getProxyInternal(boolean isFailover) {
118	    SubClusterInfo subClusterInfo;
119	    // Use the existing proxy as a backup in case getting the new proxy fails.
120	    // Note that if the first time it fails, the backup is also null. In that
121	    // case we will hit NullPointerException and throw it back to AM.
122	    T proxy = this.current;
123	    try {
124	      LOG.info("Failing over to the ResourceManager for SubClusterId: {}",
125	          subClusterId);
126	      subClusterInfo = facade.getSubCluster(subClusterId,
127	          this.flushFacadeCacheForYarnRMAddr && isFailover);
128	      // updating the conf with the refreshed RM addresses as proxy
129	      // creations are based out of conf
130	      updateRMAddress(subClusterInfo);
131	      if (this.originalUser == null) {
132	        InetSocketAddress rmAddress = rmProxy.getRMAddress(conf, protocol);
133	        LOG.info(
134	            "Connecting to {} subClusterId {} with protocol {}"
135	                + " without a proxy user",
136	            rmAddress, subClusterId, protocol.getSimpleName());
137	        proxy = createRMProxy(rmAddress);
138	      } else {
139	        // If the original ugi exists, always use that to create proxy because
140	        // it contains up-to-date AMRMToken
141	        proxy = this.originalUser.doAs(new PrivilegedExceptionAction<T>() {
142	          @Override
143	          public T run() throws IOException {
144	            InetSocketAddress rmAddress = rmProxy.getRMAddress(conf, protocol);
145	            LOG.info(
146	                "Connecting to {} subClusterId {} with protocol {} as user {}",
147	                rmAddress, subClusterId, protocol.getSimpleName(),
148	                originalUser);
149	            return createRMProxy(rmAddress);
150	          }
151	        });
152	      }
153	    } catch (Exception e) {
154	      LOG.error("Exception while trying to create proxy to the ResourceManager"
155	          + " for SubClusterId: {}", subClusterId, e);
156	      if (proxy == null) {
157	        throw new YarnRuntimeException(
158	            String.format("Create initial proxy to the ResourceManager for"
159	                + " SubClusterId %s failed", subClusterId),
160	            e);
161	      }
162	    }
163	    return proxy;
164	  }
165	
166	  private void updateRMAddress(SubClusterInfo subClusterInfo) {
167	    if (subClusterInfo != null) {
168	      if (protocol == ApplicationClientProtocol.class) {
169	        conf.set(YarnConfiguration.RM_ADDRESS,
170	            subClusterInfo.getClientRMServiceAddress());
171	      } else if (protocol == ApplicationMasterProtocol.class) {
172	        conf.set(YarnConfiguration.RM_SCHEDULER_ADDRESS,
173	            subClusterInfo.getAMRMServiceAddress());
174	      } else if (protocol == ResourceManagerAdministrationProtocol.class) {
175	        conf.set(YarnConfiguration.RM_ADMIN_ADDRESS,
176	            subClusterInfo.getRMAdminServiceAddress());
177	      }
178	    }
179	  }
180	
181	  @Override
182	  public synchronized ProxyInfo<T> getProxy() {
183	    if (current == null) {
184	      current = getProxyInternal(false);
185	    }
186	    return new ProxyInfo<T>(current, subClusterId.getId());
187	  }
188	
189	  @Override
190	  public synchronized void performFailover(T currentProxy) {
191	    // It will not return null proxy here
192	    current = getProxyInternal(federationFailoverEnabled);
193	    if (current != currentProxy) {
194	      closeInternal(currentProxy);
195	    }
196	  }
197	
198	  @Override
199	  public Class<T> getInterface() {
200	    return protocol;
201	  }
202	
203	  private void closeInternal(T currentProxy) {
204	    if (currentProxy != null) {
205	      if (currentProxy instanceof Closeable) {
206	        try {
207	          ((Closeable) currentProxy).close();
208	        } catch (IOException e) {
209	          LOG.warn("Exception while trying to close proxy", e);
210	        }
211	      } else {
212	        RPC.stopProxy(currentProxy);
213	      }
214	    }
215	  }
216	
217	  /**
218	   * Close all the proxy objects which have been opened over the lifetime of
219	   * this proxy provider.
220	   */
221	  @Override
222	  public synchronized void close() throws IOException {
223	    closeInternal(current);
224	  }
225	
226	}
