102	  private void testProxyProvider(boolean facadeFlushCache) throws Exception {
103	    final SubClusterId subClusterId = SubClusterId.newInstance("SC-1");
104	    final MiniYARNCluster cluster = new MiniYARNCluster(
105	        "testFederationRMFailoverProxyProvider", 3, 0, 1, 1);
106	
107	    conf.setBoolean(YarnConfiguration.FEDERATION_FLUSH_CACHE_FOR_RM_ADDR,
108	        facadeFlushCache);
109	
110	    conf.setBoolean(YarnConfiguration.RM_HA_ENABLED, true);
111	    conf.setBoolean(YarnConfiguration.AUTO_FAILOVER_ENABLED, false);
112	    conf.set(YarnConfiguration.RM_CLUSTER_ID, "cluster1");
113	    conf.set(YarnConfiguration.RM_HA_IDS, "rm1,rm2,rm3");
114	
115	    conf.setLong(YarnConfiguration.RESOURCEMANAGER_CONNECT_RETRY_INTERVAL_MS,
116	        2000);
117	
118	    HATestUtil.setRpcAddressForRM("rm1", 10000, conf);
119	    HATestUtil.setRpcAddressForRM("rm2", 20000, conf);
120	    HATestUtil.setRpcAddressForRM("rm3", 30000, conf);
121	    conf.setBoolean(YarnConfiguration.YARN_MINICLUSTER_FIXED_PORTS, true);
122	
123	    cluster.init(conf);
124	    cluster.start();
125	
126	    // Transition rm3 to active;
127	    makeRMActive(subClusterId, cluster, 2);
128	
129	    ApplicationClientProtocol client = FederationProxyProviderUtil
130	        .createRMProxy(conf, ApplicationClientProtocol.class, subClusterId,
131	            UserGroupInformation.getCurrentUser());
132	
133	    verify(stateStore, times(1))
134	        .getSubClusters(any(GetSubClustersInfoRequest.class));
135	
136	    // client will retry until the rm becomes active.
137	    GetClusterMetricsResponse response =
138	        client.getClusterMetrics(GetClusterMetricsRequest.newInstance());
139	
140	    verify(stateStore, times(1))
141	        .getSubClusters(any(GetSubClustersInfoRequest.class));
142	
143	    // validate response
144	    checkResponse(response);
145	
146	    // transition rm3 to standby
147	    cluster.getResourceManager(2).getRMContext().getRMAdminService()
148	        .transitionToStandby(new HAServiceProtocol.StateChangeRequestInfo(
149	            HAServiceProtocol.RequestSource.REQUEST_BY_USER));
150	
151	    // Transition rm2 to active;
152	    makeRMActive(subClusterId, cluster, 1);
153	
154	    verify(stateStore, times(1))
155	        .getSubClusters(any(GetSubClustersInfoRequest.class));
156	
157	    threadResponse = null;
158	    Thread thread = new Thread(new Runnable() {
159	      @Override
160	      public void run() {
161	        try {
162	          // In non flush cache case, we will be hitting the cache with old RM
163	          // address and keep failing before the cache is flushed
164	          threadResponse =
165	              client.getClusterMetrics(GetClusterMetricsRequest.newInstance());
166	        } catch (YarnException | IOException e) {
167	          e.printStackTrace();
168	        }
169	      }
170	    });
171	    thread.start();
172	
173	    if (!facadeFlushCache) {
174	      // Add a wait so that hopefully the thread has started hitting old cached
175	      Thread.sleep(500);
176	
177	      // Should still be hitting cache
178	      verify(stateStore, times(1))
179	          .getSubClusters(any(GetSubClustersInfoRequest.class));
180	
181	      // Force flush cache, so that it will pick up the new RM address
182	      FederationStateStoreFacade.getInstance().getSubCluster(subClusterId,
183	          true);
184	    }
185	
186	    // Wait for the thread to finish and grab result
187	    thread.join();
188	    response = threadResponse;
189	
190	    if (facadeFlushCache) {
191	      verify(stateStore, atLeast(2))
192	          .getSubClusters(any(GetSubClustersInfoRequest.class));
193	    } else {
194	      verify(stateStore, times(2))
195	          .getSubClusters(any(GetSubClustersInfoRequest.class));
196	    }
197	
198	    // validate response
199	    checkResponse(response);
200	
201	    cluster.stop();
202	  }
