104	  /**
105	   * Verify that the RPC layer is always created using the correct UGI from the
106	   * RMProxy.  It should always use the UGI from creation in subsequent uses,
107	   * even outside of a doAs.
108	   *
109	   * @throws Exception an Exception occurred
110	   */
111	  @Test
112	  public void testProxyUserCorrectUGI() throws Exception {
113	    final YarnConfiguration conf = new YarnConfiguration();
114	    conf.setBoolean(YarnConfiguration.RM_HA_ENABLED, true);
115	    conf.set(YarnConfiguration.RM_HA_IDS, "rm1,rm2");
116	    conf.set(HAUtil.addSuffix(YarnConfiguration.RM_HOSTNAME, "rm1"),
117	        "0.0.0.0");
118	    conf.set(HAUtil.addSuffix(YarnConfiguration.RM_HOSTNAME, "rm2"),
119	        "0.0.0.0");
120	    conf.setLong(YarnConfiguration.CLIENT_FAILOVER_MAX_ATTEMPTS, 2);
121	    conf.setLong(YarnConfiguration.RESOURCEMANAGER_CONNECT_MAX_WAIT_MS, 2);
122	    conf.setLong(
123	        YarnConfiguration.RESOURCEMANAGER_CONNECT_RETRY_INTERVAL_MS, 2);
124	
125	    // Replace the RPC implementation with one that will capture the current UGI
126	    conf.setClass(YarnConfiguration.IPC_RPC_IMPL,
127	        UGICapturingHadoopYarnProtoRPC.class, YarnRPC.class);
128	
129	    UserGroupInformation realUser = UserGroupInformation.getCurrentUser();
130	    UserGroupInformation proxyUser =
131	        UserGroupInformation.createProxyUserForTesting("proxy", realUser,
132	        new String[] {"group1"});
133	
134	    // Create the RMProxy using the proxyUser
135	    ApplicationClientProtocol rmProxy = proxyUser.doAs(
136	        new PrivilegedExceptionAction<ApplicationClientProtocol>() {
137	          @Override
138	          public ApplicationClientProtocol run() throws Exception {
139	            return ClientRMProxy.createRMProxy(conf,
140	                ApplicationClientProtocol.class);
141	          }
142	        });
143	
144	    // It was in a doAs, so the UGI should be correct
145	    assertUGI();
146	
147	    // Try to use the RMProxy, which should trigger the RPC again
148	    GetNewApplicationRequest request =
149	        Records.newRecord(GetNewApplicationRequest.class);
150	    UGICapturingHadoopYarnProtoRPC.lastCurrentUser = null;
151	    try {
152	      rmProxy.getNewApplication(request);
153	    } catch (IOException ioe) {
154	      // ignore - RMs are not running so this is expected to fail
155	    }
156	
157	    // This time it was outside a doAs, but make sure the UGI was still correct
158	    assertUGI();
159	  }
