161	  private void assertUGI() throws IOException {
162	    UserGroupInformation lastCurrentUser =
163	        UGICapturingHadoopYarnProtoRPC.lastCurrentUser;
164	    assertNotNull(lastCurrentUser);
165	    assertEquals("proxy", lastCurrentUser.getShortUserName());
166	    Assert.assertEquals(UserGroupInformation.AuthenticationMethod.PROXY,
167	        lastCurrentUser.getAuthenticationMethod());
168	    assertEquals(UserGroupInformation.getCurrentUser(),
169	        lastCurrentUser.getRealUser());
170	    // Reset UGICapturingHadoopYarnProtoRPC
171	    UGICapturingHadoopYarnProtoRPC.lastCurrentUser = null;
172	  }
