174	  /**
175	   * Subclass of {@link HadoopYarnProtoRPC} which captures the current UGI in
176	   * a static variable.  Used by {@link #testProxyUserCorrectUGI()}.
177	   */
178	  public static class UGICapturingHadoopYarnProtoRPC
179	      extends HadoopYarnProtoRPC {
